    + "    origin: Int,\n"
    + "    capacity: Int,\n"
    + "    height: Int,\n"
    + "    root: Tree(a),\n"
    + "    tail: Node(a),\n"
    + "}\n"
    + "\n"
    + "// Signals a structurally malformed trie (a runtime bug, never a caller error).\n"
    + "// Thrown only on paths a well-formed trie can never take.\n"
