    + "    let internal = index + trie.origin\n"
    + "    let off = tailOffset(trie.capacity)\n"
    + "    if internal >= off then\n"
    + "        (trie.tail, internal - off, trie.capacity - internal)\n"
    + "    else\n"
    + "        var node: Tree(a) = trie.root\n"
    + "        var span = pow32(trie.height - 1)\n"
