    + "        for level in 2..trie.height\n"
    + "            node := match node\n"
    + "                Branch(children) => Node.get(children, Int.div(remaining, span))\n"
    + "                Leaf(_) => node\n"
    + "            remaining := Int.mod(remaining, span)\n"
    + "            span := Int.div(span, radix)\n"
