    + "\n"
    + "// Wraps `leaf` in `levels` fresh branch nodes, forming the left spine of a new\n"
    + "// subtree. `newPath(0, leaf) = leaf`.\n"
    + "fun newPath<a>(levels: Int, leaf: Tree(a)): Tree(a) =\n"
    + "    var node: Tree(a) = leaf\n"
    + "    for step in 1..levels\n"
    + "        node := Branch(Node.set(Node.empty(), 0, node))\n"
    + "    node\n"
    + "\n"
    + "// Inserts `leaf` at 0-based leaf position `p` into a copy of `node` (a height-`h`\n"
